release_tag_anchor() {
  local tag
  tag="$(git -C "$1" describe --tags --abbrev=0 --match "$RELEASE_TAG_GLOB" "$2" 2>&1)" || {
    printf '%s\n' "$tag"
    return 1
  }
  case "$tag" in
    v[0-9]*.[0-9]*.[0-9]*) printf '%s\n' "$tag" ;;
    *)
      printf 'resolved %s, which is not a release tag\n' "$tag"
      return 1
      ;;
  esac
}
